head.script:
// 화면 리사이징

scwin.gAcptNo;

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    await scwin.gform_onload();
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name setCode
 * @description 기간 from~ to  셋팅
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {
    //  기간 from~ to  셋팅
    vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_FromDate.setValue($c.ut.cGetMinusDate2(vCurDate, 7)); // 일주일전 날짜
    // edt_FromDate.text = vCurDate;     // 현재날짜
    edt_ToDate.setValue(vCurDate); // 현재날짜

    const sbmOptions = {
        id : "sbm_dts_SecuGrpID",
        action : "/DisclosureSearch.do",
        ref : "",
        target : "dts_SecuGrpID=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name myFormNmList
 * @description 사용자서식 명칭 리스트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.myFormNmList = async function() {
    // 사용자서식 명칭 리스트
    const sbmOptions = {
        id : "sbm_dts_myFormNmList",
        action : "/MyFormPage.do",
        ref : "",
        target : "dts_myFormNmList=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************

};X < !공시상세--;
목록검색;
클릭-- > async function() {
    const vFormCd = txb_FormCd.getValue();
    const vFormNm = txb_FormNm.getValue();

    // 일자 체크
    if (edt_FromDate.getValue().length < 8) {
        await $c.win.alert("일자 올바르게 입력하십시오.");
        edt_FromDate.focus();
        return;
    }

    // 일자 체크
    if (edt_ToDate.getValue().length < 8) {
        await $c.win.alert("일자 올바르게 입력하십시오.");
        edt_ToDate.focus();
        return;
    }
    if ($c.stf.compareFromToDate2(edt_FromDate, edt_ToDate) === false) {
        return;
    }

    // 보고서코그 체크
    if (vFormCd.length > 0 && vFormCd.length !== 5) {
        await $c.win.alert("서식코드 5자리를 입력하십시오.");
        txb_FormCd.focus();
        return;
    }
    fn_Search();
} < !공시상세--;
클릭-- > async function() {
    const edt_FromDate_year = edt_FromDate.getValue().substr(0, 4);
    const edt_FromDate_month = edt_FromDate.getValue().substr(4, 2) - 1;
    const edt_FromDate_day = edt_FromDate.getValue().substr(6, 2);
    const edt_FromDate_Date = new Date(edt_FromDate_year, edt_FromDate_month, edt_FromDate_day);
    const edt_ToDate_year = edt_ToDate.getValue().substr(0, 4);
    const edt_ToDate_month = edt_ToDate.getValue().substr(4, 2) - 1;
    const edt_ToDate_day = edt_ToDate.getValue().substr(6, 2);
    const edt_ToDate_Date = new Date(edt_ToDate_year, edt_ToDate_month, edt_ToDate_day);

    // 회사코드 조건없이 3년 이상의 기간은 검색 할 수 없다
    const company_code = txb_isur_cd.getValue();
    const date_result = (Date.parse(edt_ToDate_Date) - Date.parse(edt_FromDate_Date)) / (1000 * 60 * 60 * 24);
    if (!company_code && date_result > 1096) {
        await $c.win.alert("검색기간 3년 이상 조회시 회사코드를 필수로 선택하여야 합니다.");
        return;
    }
    const sbmOptions = {
        id : "sbm_dts_DsclList",
        action : "/DisclosureSearch.do",
        ref : "",
        target : "dts_DsclList=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name getChkValue
 * @description get Chk Value 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.getChkValue = function(obj) {
    if (obj.checked === true) {
        return obj.getValue();
    } else {
        return "0";
    }
};

/**
 * @method
 * @name setContnId
 * @description 그리드에서 클릭 row의 변수셋팅
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setContnId = function(obj) {
    scwin.gAcptNo = dts_DsclList.getCellData(Number(obj), "ACPT_NO");
};

/**
 * @method
 * @name ulyIsuDown
 * @description uly Isu Down 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ulyIsuDown = async function() {
    // vComAttrTpCd = cmb_StockOrEtf.ValueOfIndex("VALUE", cmb_StockOrEtf.Index);

    const sbmOptions = {
        id : "sbm_dts_UlyIsuList",
        action : "/DisclosureSearch.do",
        ref : "",
        target : "dts_UlyIsuList=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    $c.data.downloadGridViewExcel(grd_UlyIsuList, {fileName: "주식선물/옵션 기초자산 현황", type: "8"});
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Search_onclick = function() {
    fn_CheckCond();
};

/**
 * @method
 * @name btn_myForm_onclick
 * @description 「사용자서식관리」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_myForm_onclick = async function() {
    const options = {
        id: "ULDSTF51000",
        title: "사용자서식관리",
        type: "browserPopup",
        width: "1300px",
        height: "750px",
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("/indinfo/ULDSTF51000.gfm", options);
};

/**
 * @method
 * @name dts_DsclList_OnLoadError
 * @description dts_DsclList 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_DsclList_OnLoadError = async function() {
    await $c.win.alert(dts_DsclList.errorMsg);
};

/**
 * @method
 * @name dts_DsclList_OnLoadCompleted
 * @description dts_DsclList 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_DsclList_OnLoadCompleted = async function(rowcount) {
    if (dts_DsclList.errorMsg) {
        await $c.win.alert("OnLoadCompleted => " + dts_DsclList.errorMsg);
    } else {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
    }
};

/**
 * @method
 * @name dts_SecuGrpID_OnLoadError
 * @description dts_SecuGrpID 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_SecuGrpID_OnLoadError = async function() {
    await $c.win.alert(dts_UlyIsuCnt.errorMsg);
};

/**
 * @method
 * @name dts_SecuGrpID_OnLoadCompleted
 * @description dts_SecuGrpID 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_SecuGrpID_OnLoadCompleted = async function(rowcount) {
    // vComAttrTpCd = cmb_StockOrEtf.ValueOfIndex("VALUE", cmb_StockOrEtf.Index);

    const sbmOptions = {
        id : "sbm_dts_UlyIsuCnt",
        action : "/DisclosureSearch.do",
        ref : "",
        target : "dts_UlyIsuCnt=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const ulyIsuCnt = dts_UlyIsuCnt.getCellData(dts_UlyIsuCnt.getRowCount(), "TEXT"); // 기초자산 종목수 2018.09.14

    const vTotalArea = "<a style='border:1px; border-style__dashed; padding:3; cursor:pointer;'><span style='font-size__9pt; font-family:굴림; color:#212863;'>기초자산 종목수: </span><span style='font-size__9pt; font-family:굴림; color:#5C8BE0; font-weight:bold;'>" + ulyIsuCnt + "</span></a>";
    panel_uly_isu.innerHTML = "<table border='0' cellpadding='0' cellspacing='0' height='22' width='100%'>" + "    <tr>" + "        <td align='left' width='2%' nowrap>" + vTotalArea + "</td>" + "        <td align='center'></td>" + "        <td align='right' width='30'></td>" + "        <td align='right' width='2%' nowrap>&nbsp;</td>" + "    </tr>" + "</table>";
};

/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description 클릭된 값 변수에 셋팅
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    // 클릭된 값 변수에 셋팅
    scwin.setContnId(row);
    if (colid === "DOC_TITLE") {
        // 2017-11-28 KBoY 비공개 첨부서류 볼 수 없음.
        await $c.stf.openDisclViewer(scwin.gAcptNo, "R", 'ULDSTF15410.xml');
    }
};

/**
 * @method
 * @name img_FromCal_onclick
 * @description img_FromCal 클릭 이벤트
 * @returns {void}
