    Grd_com_isur.style.display = "none";
};

/**
 * @method
 * @name gform_onload
 * @description 패널라운드 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.gform_onload = async function() {
    // 패널라운드 처리
    $c.cm.PanelToGroupBox(panel_1);
    await scwin.setCode();
    $c.stf.comboCbDataSetPeriod(cmb_PeriodTp);
    $c.cm.fn_com_isur_futures(txb_isur_cd, txb_com_abbrv);
    grd_UlyIsuList.hide(); // 엑셀다운로드용 그리드 숨기기

    fn_CheckCond();
    await scwin.myFormNmList();
};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};
